//! 🧪️ Neutral cooperative traces replay the same committed prefix with different preparation work.
use super::*;
fn marker(value:&serde_json::Value)->ExportMilestone{ExportMilestone{stage:value["stage"].as_u64().unwrap()as u8,raw_bytes:value["rawBytes"].as_u64().unwrap()as usize,encoded_bytes:value["encodedBytes"].as_u64().unwrap()as usize,published_chunks:value["publishedChunks"].as_u64().unwrap()as usize}}
#[test]fn replay_milestones_ignore_preparation_grain_and_reject_mismatched_prefixes(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let source=row["source"].as_array().unwrap();let cut=row["checkpointAt"].as_u64().unwrap()as usize;let target=marker(&source[cut]);let committed=source[..=cut].windows(2).filter(|pair|committed_milestone(marker(&pair[0]),marker(&pair[1]))).count()as u64;assert_eq!(committed,row["expectedCommitted"].as_u64().unwrap());let replay=row["replay"].as_array().unwrap();let mut current=0;let mut matched=false;for at in 0..replay.len(){if at>0{current+=u64::from(committed_milestone(marker(&replay[at-1]),marker(&replay[at])));}if replay_position(current,committed,marker(&replay[at])==target,false).unwrap(){matched=true;break;}}assert!(matched);assert!(replay_position(committed+1,committed,true,false).is_err());assert!(replay_position(committed,committed,false,false).is_err());assert!(replay_position(committed,committed+1,false,true).is_err());}}
